INSERT INTO guard_fail(code) SELECT 'precondition_changed' WHERE EXISTS(SELECT 1 FROM core_authority_activation);
CREATE TABLE project_r2_bucket_reservations (
 organization_id TEXT NOT NULL CHECK(length(organization_id)=26 AND length(CAST(organization_id AS BLOB))=26 AND organization_id GLOB '[0-7]*' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),project_id TEXT NOT NULL CHECK(length(project_id)=26 AND length(CAST(project_id AS BLOB))=26 AND project_id GLOB '[0-7]*' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),environment_id TEXT NOT NULL CHECK(length(environment_id)=26 AND length(CAST(environment_id AS BLOB))=26 AND environment_id GLOB '[0-7]*' AND environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),operation_id TEXT NOT NULL CHECK(length(operation_id)=26 AND length(CAST(operation_id AS BLOB))=26 AND operation_id GLOB '[0-7]*' AND operation_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),claim_id TEXT NOT NULL CHECK(length(claim_id)=26 AND length(CAST(claim_id AS BLOB))=26 AND claim_id GLOB '[0-7]*' AND claim_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),bucket_name TEXT NOT NULL,jurisdiction TEXT NOT NULL CHECK(jurisdiction IN('eu','us')),
 storage_class TEXT NOT NULL CHECK(storage_class='Standard'),public_access INTEGER NOT NULL CHECK(public_access=0),
 reserved_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now')||'000Z') CHECK(reserved_at IN('-infinity','+infinity') OR (reserved_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(reserved_at AS BLOB))=27)),create_started_at TEXT,
 PRIMARY KEY(organization_id,project_id,environment_id),
 FOREIGN KEY(claim_id,organization_id,project_id,environment_id,operation_id) REFERENCES product_provider_mutation_claims(claim_id,organization_id,project_id,environment_id,operation_id) ON DELETE RESTRICT,
 CHECK(bucket_name='ohmyho-'||lower(project_id)||'-'||lower(environment_id)),
 CHECK(create_started_at IS NULL OR create_started_at>=reserved_at)
) STRICT, WITHOUT ROWID;
CREATE TRIGGER project_r2_bucket_reservations_once BEFORE UPDATE ON project_r2_bucket_reservations
 WHEN OLD.create_started_at IS NOT NULL OR NEW.create_started_at IS NULL OR NEW.organization_id IS NOT OLD.organization_id OR NEW.project_id IS NOT OLD.project_id OR NEW.environment_id IS NOT OLD.environment_id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.claim_id IS NOT OLD.claim_id OR NEW.bucket_name IS NOT OLD.bucket_name OR NEW.jurisdiction IS NOT OLD.jurisdiction OR NEW.storage_class IS NOT OLD.storage_class OR NEW.public_access IS NOT OLD.public_access OR NEW.reserved_at IS NOT OLD.reserved_at
 BEGIN SELECT RAISE(ABORT,'R2 bucket reservation permits only one create authorization'); END;
CREATE TRIGGER project_r2_bucket_reservations_delete BEFORE DELETE ON project_r2_bucket_reservations
 WHEN NOT EXISTS(SELECT 1 FROM project_r2_bucket_receipts r WHERE r.organization_id=OLD.organization_id AND r.project_id=OLD.project_id AND r.environment_id=OLD.environment_id AND r.claim_id=OLD.claim_id)
 BEGIN SELECT RAISE(ABORT,'active R2 bucket reservation cannot be deleted'); END;
CREATE TABLE project_r2_upload_reservations (
 transfer_id TEXT NOT NULL CHECK(length(transfer_id)=26 AND length(CAST(transfer_id AS BLOB))=26 AND transfer_id GLOB '[0-7]*' AND transfer_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),organization_id TEXT NOT NULL CHECK(length(organization_id)=26 AND length(CAST(organization_id AS BLOB))=26 AND organization_id GLOB '[0-7]*' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),project_id TEXT NOT NULL CHECK(length(project_id)=26 AND length(CAST(project_id AS BLOB))=26 AND project_id GLOB '[0-7]*' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),environment_id TEXT NOT NULL CHECK(length(environment_id)=26 AND length(CAST(environment_id AS BLOB))=26 AND environment_id GLOB '[0-7]*' AND environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),idempotency_key TEXT NOT NULL CHECK(length(idempotency_key)<=128 AND instr(idempotency_key,char(0))=0),
 request_sha256 BLOB NOT NULL CHECK(length(request_sha256)=32),object_key TEXT NOT NULL CHECK(instr(object_key,char(0))=0 AND length(CAST(object_key AS BLOB)) BETWEEN 1 AND 512 AND object_key NOT GLOB '*[^A-Za-z0-9._/-]*' AND object_key NOT LIKE '/%' AND object_key NOT LIKE '%/' AND object_key NOT LIKE '%//%' AND ('/'||object_key||'/') NOT LIKE '%/./%' AND ('/'||object_key||'/') NOT LIKE '%/../%'),content_type TEXT NOT NULL CHECK(instr(content_type,char(0))=0 AND content_type NOT GLOB '*[^a-z0-9!#$&^_.+/-]*' AND instr(content_type,'/') BETWEEN 2 AND 65 AND length(substr(content_type,instr(content_type,'/')+1)) BETWEEN 1 AND 64 AND substr(content_type,1,1) GLOB '[a-z0-9]' AND substr(content_type,instr(content_type,'/')+1,1) GLOB '[a-z0-9]' AND instr(substr(content_type,instr(content_type,'/')+1),'/')=0),
 expected_bytes INTEGER NOT NULL CHECK(expected_bytes BETWEEN 0 AND 1073741824),requested_at TEXT NOT NULL  CHECK(requested_at IN('-infinity','+infinity') OR (requested_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(requested_at AS BLOB))=27)),expires_at TEXT NOT NULL  CHECK(expires_at IN('-infinity','+infinity') OR (expires_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(expires_at AS BLOB))=27)),
 data_environment_id TEXT NOT NULL CHECK(length(data_environment_id)=26 AND length(CAST(data_environment_id AS BLOB))=26 AND data_environment_id GLOB '[0-7]*' AND data_environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),physical_object_key TEXT NOT NULL CHECK(instr(physical_object_key,char(0))=0 AND length(CAST(physical_object_key AS BLOB)) BETWEEN 1 AND 544),logical_namespace_version INTEGER NOT NULL DEFAULT 1 CHECK(logical_namespace_version IN(1,2)),
 PRIMARY KEY(transfer_id),UNIQUE(organization_id,project_id,environment_id,data_environment_id,idempotency_key),UNIQUE(organization_id,project_id,environment_id,physical_object_key),
 FOREIGN KEY(organization_id,project_id,environment_id) REFERENCES project_r2_bucket_receipts(organization_id,project_id,environment_id) ON DELETE RESTRICT,FOREIGN KEY(organization_id,project_id,data_environment_id) REFERENCES project_data_environments(organization_id,project_id,data_environment_id) ON DELETE RESTRICT,CHECK(expires_at>requested_at AND expires_at<=strftime('%Y-%m-%dT%H:%M:%S',requested_at,'+5 minutes')||substr(requested_at,20))
) STRICT, WITHOUT ROWID;
CREATE UNIQUE INDEX project_r2_upload_object_key_v2 ON project_r2_upload_reservations(organization_id,project_id,data_environment_id,object_key) WHERE logical_namespace_version=2;
CREATE TABLE project_r2_objects (
 organization_id TEXT NOT NULL CHECK(length(organization_id)=26 AND length(CAST(organization_id AS BLOB))=26 AND organization_id GLOB '[0-7]*' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),project_id TEXT NOT NULL CHECK(length(project_id)=26 AND length(CAST(project_id AS BLOB))=26 AND project_id GLOB '[0-7]*' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),environment_id TEXT NOT NULL CHECK(length(environment_id)=26 AND length(CAST(environment_id AS BLOB))=26 AND environment_id GLOB '[0-7]*' AND environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),transfer_id TEXT NOT NULL CHECK(length(transfer_id)=26 AND length(CAST(transfer_id AS BLOB))=26 AND transfer_id GLOB '[0-7]*' AND transfer_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),object_key TEXT NOT NULL CHECK(instr(object_key,char(0))=0),content_type TEXT NOT NULL CHECK(instr(content_type,char(0))=0),
 size INTEGER NOT NULL CHECK(size BETWEEN 0 AND 1073741824),etag TEXT NOT NULL CHECK(length(CAST(etag AS BLOB))=length(etag) AND substr(etag,1,32) NOT GLOB '*[^0-9a-f]*' AND (length(etag)=32 OR(length(etag) BETWEEN 34 AND 38 AND substr(etag,33,1)='-' AND substr(etag,34) GLOB '[1-9]*' AND substr(etag,34) NOT GLOB '*[^0-9]*'))),
 uploaded_at TEXT NOT NULL  CHECK(uploaded_at IN('-infinity','+infinity') OR (uploaded_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(uploaded_at AS BLOB))=27)),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now')||'000Z') CHECK(created_at IN('-infinity','+infinity') OR (created_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(created_at AS BLOB))=27)),data_environment_id TEXT NOT NULL CHECK(length(data_environment_id)=26 AND length(CAST(data_environment_id AS BLOB))=26 AND data_environment_id GLOB '[0-7]*' AND data_environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),physical_object_key TEXT NOT NULL CHECK(instr(physical_object_key,char(0))=0 AND length(CAST(physical_object_key AS BLOB)) BETWEEN 1 AND 544),
 PRIMARY KEY(organization_id,project_id,environment_id,physical_object_key),UNIQUE(transfer_id),FOREIGN KEY(transfer_id) REFERENCES project_r2_upload_reservations(transfer_id) ON DELETE RESTRICT,FOREIGN KEY(organization_id,project_id,data_environment_id) REFERENCES project_data_environments(organization_id,project_id,data_environment_id) ON DELETE RESTRICT
