CREATE TABLE provider_collection_cursors (
 provider_kind TEXT NOT NULL CHECK(provider_kind IN('neon','r2')),account_id TEXT NOT NULL,
 after_resource_key TEXT NOT NULL DEFAULT '' CHECK(length(after_resource_key)<=256 AND instr(after_resource_key,char(0))=0),generation INTEGER NOT NULL DEFAULT 0 CHECK(generation>=0),
 next_request_at TEXT NOT NULL DEFAULT '-infinity' CHECK(next_request_at IN('-infinity','+infinity') OR (next_request_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(next_request_at AS BLOB))=27)),cycle_started_at TEXT NOT NULL DEFAULT '-infinity' CHECK(cycle_started_at IN('-infinity','+infinity') OR (cycle_started_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(cycle_started_at AS BLOB))=27)),next_cycle_at TEXT NOT NULL DEFAULT '-infinity' CHECK(next_cycle_at IN('-infinity','+infinity') OR (next_cycle_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(next_cycle_at AS BLOB))=27)),
 PRIMARY KEY(provider_kind,account_id),CHECK((provider_kind='r2' AND length(account_id)=32 AND length(CAST(account_id AS BLOB))=32 AND account_id NOT GLOB '*[^0-9a-f]*') OR(provider_kind='neon' AND substr(account_id,1,4)='org-' AND length(account_id) BETWEEN 5 AND 60 AND substr(account_id,5) NOT GLOB '*[^a-z0-9-]*'))
) STRICT, WITHOUT ROWID;
CREATE INDEX provider_collection_r2_resource_idx ON project_r2_bucket_receipts((bucket_name||'/'||jurisdiction));
CREATE TRIGGER provider_collection_cursors_no_delete BEFORE DELETE ON provider_collection_cursors BEGIN SELECT RAISE(ABORT,'Provider collection cursor mutation denied'); END;
CREATE TRIGGER provider_collection_cursors_guard BEFORE UPDATE ON provider_collection_cursors
 WHEN NEW.provider_kind IS NOT OLD.provider_kind OR NEW.account_id IS NOT OLD.account_id OR NEW.generation<OLD.generation OR NEW.generation>OLD.generation+1 OR(NEW.after_resource_key IS NOT OLD.after_resource_key AND NEW.generation<>OLD.generation+1)
 OR (OLD.next_request_at='+infinity' AND NEW.next_request_at<>'+infinity') OR(OLD.next_request_at<>'-infinity' AND NEW.next_request_at='-infinity') OR(OLD.next_request_at NOT IN('-infinity','+infinity') AND NEW.next_request_at NOT IN('-infinity','+infinity') AND NEW.next_request_at<OLD.next_request_at)
 BEGIN SELECT RAISE(ABORT,'Provider collection cursor mutation denied'); END;
